import React, { useState } from 'react';
import { Leaf } from 'lucide-react';

export default function App() {
  const [lang, setLang] = useState('en');
  return (
    <div className="min-h-screen bg-[#F6F5F0] text-[#1E2E26] p-8">
      <header className="flex items-center justify-between max-w-5xl mx-auto pb-8">
        <div className="flex items-center gap-2 font-semibold text-xl text-[#3E6B52]">
          <Leaf className="w-6 h-6" /> MindSutra
        </div>
        <select value={lang} onChange={e => setLang(e.target.value)} className="border rounded-full px-3 py-1 text-sm">
          <option value="en">English</option>
          <option value="kn">ಕನ್ನಡ</option>
          <option value="hi">हिंदी</option>
        </select>
      </header>
      <main className="max-w-5xl mx-auto text-center py-12 space-y-4">
        <h1 className="text-4xl font-serif font-semibold">Calm mind, rooted presence — in your language.</h1>
        <p className="opacity-80">Multilingual AI meditation guidance, interactive breathwork, and soothing soundscapes.</p>
      </main>
    </div>
  );
}
